-- Read-only regression of candidate peak occupancy algorithm. Does not test concurrent transactions or deployed trigger.
WITH cases(name,capacity,expected) AS (VALUES ('empty',1,0),('adjacent',2,1),('overlap',2,2),('nested',3,3),('outside',1,0),('clipped',2,1)), intervals(name,s,e) AS (VALUES ('adjacent',1,3),('adjacent',3,5),('overlap',1,4),('overlap',2,5),('nested',1,5),('nested',2,4),('nested',3,4),('outside',-2,0),('outside',6,8),('clipped',-2,2),('clipped',4,8)), clipped AS (SELECT name,greatest(s,0) s,least(e,6) e FROM intervals WHERE s<6 AND e>0), events AS (SELECT name,s t,1 delta FROM clipped UNION ALL SELECT name,e,-1 FROM clipped), grouped AS (SELECT name,t,sum(delta) delta FROM events GROUP BY name,t), running AS (SELECT name,sum(delta) OVER(PARTITION BY name ORDER BY t) n FROM grouped), peaks AS (SELECT name,max(n) peak FROM running GROUP BY name) SELECT c.name,coalesce(p.peak,0) peak,c.expected,coalesce(p.peak,0)=c.expected passed,coalesce(p.peak,0)<c.capacity can_accept FROM cases c LEFT JOIN peaks p USING(name) ORDER BY name;
